let tables = {Tables};
let rows = Usage | where TimeGenerated < startofday(now());
let firstHour = toscalar(rows | summarize min(TimeGenerated));
// Whole UTC days only: the time range starts mid-day, so a partial first day is skipped. Days count from all of Usage,
// so a table that logs only some days is still averaged over the whole range.
let start = iff(firstHour == startofday(firstHour), firstHour, startofday(firstHour) + 1d);
let days = max_of(1, coalesce(datetime_diff("day", startofday(now()), start), 0));
let usage = rows
| where TimeGenerated >= start and IsBillable == true
| where array_length(tables) == 0 or DataType in (tables)
| extend Plan = tostring(column_ifexists("Plan", ""))
| extend Plan = iff(isempty(Plan), "Analytics", Plan);
let total = toscalar(usage | summarize sum(Quantity)) / 1000.0;
usage
| summarize GB = sum(Quantity) / 1000.0 by Table = DataType, Plan
| extend GBPerDay = GB / days
| extend IngestPerMonth = GBPerDay * 30 * case(Plan == "Analytics", {PriceAnalytics}, Plan == "Basic", {PriceBasic}, Plan == "Auxiliary", {PriceAuxiliary}, real(null))
| extend RetentionPerMonth = GBPerDay * max_of(0, {RetentionDays} - iff(Plan == "Analytics", {FreeRetentionDays}, 30)) * {RetentionPrice}
| extend TotalPerMonth = IngestPerMonth + RetentionPerMonth, SharePct = round(100.0 * GB / total, 1)
| summarize GBPerDay = round(sum(GBPerDay), 3), IngestPerMonth = round(sum(IngestPerMonth), 2), RetentionPerMonth = round(sum(RetentionPerMonth), 2), TotalPerMonth = round(sum(TotalPerMonth), 2)
| project GBPerDay

