let tables = {Tables};
let usage = Usage
| where TimeGenerated < startofday(now()) and IsBillable == true
| where array_length(tables) == 0 or DataType in (tables);
let top10 = usage | summarize GB = sum(Quantity) by DataType | top 10 by GB | project DataType;
usage
| where DataType in (top10)
| summarize GB = round(sum(Quantity) / 1000.0, 3) by Day = bin(TimeGenerated, 1d), Table = DataType
| order by Day asc

let rows = Usage | where TimeGenerated < startofday(now());
let firstHour = toscalar(rows | summarize min(TimeGenerated));
// Whole UTC days only: the time range starts mid-day, so a partial first day is skipped. Days count from all of Usage,
// so a table that logs only some days is still averaged over the whole range.
let start = iff(firstHour == startofday(firstHour), firstHour, startofday(firstHour) + 1d);
let days = max_of(1, coalesce(datetime_diff("day", startofday(now()), start), 0));
let usage = rows
| where TimeGenerated >= start and IsBillable == true
| extend Plan = tostring(column_ifexists("Plan", ""))
| extend Plan = iff(isempty(Plan), "Analytics", Plan);
let analytics = toscalar(usage | where Plan == "Analytics" | summarize sum(Quantity)) / 1000.0 / days;
let scale = {PriceAnalytics} / 4.30;
// East US Sentinel simplified commitment tiers (USD per day, November 2026), scaled by your Analytics price: an approximation,
// as regional tier discounts differ.
union
    (print Option = "Pay-as-you-go", TierGB = 0, PerDay = analytics * {PriceAnalytics}),
    (datatable(TierGB: long, TierPrice: real) [100, 296.0, 200, 548.0, 300, 800.0, 400, 1037.33, 500, 1265.0, 1000, 2480.0, 2000, 4800.0, 5000, 11550.0]
    | extend Option = strcat(TierGB, " GB/day"), PerDay = scale * (TierPrice + max_of(0.0, analytics - TierGB) * TierPrice / TierGB)
    | project Option, TierGB, PerDay)
| extend AnalyticsGBPerDay = round(analytics, 2), PerMonth = round(PerDay * 30, 2), PerDay = round(PerDay, 2)
| order by TierGB asc
| project Option, AnalyticsGBPerDay, PerDay, PerMonth

// Billed size is about 25% smaller than the raw JSON an event is sent as.
let gbPerDay = 1.0 * {EventsPerDay} * {BytesPerEvent} * 0.75 / 1e9;
datatable(Plan: string) ["Analytics", "Basic", "Auxiliary"]
| extend PricePerGB = case(Plan == "Analytics", {PriceAnalytics}, Plan == "Basic", {PriceBasic}, Plan == "Auxiliary", {PriceAuxiliary}, real(null)), FreeDays = iff(Plan == "Analytics", {FreeRetentionDays}, 30)
| extend GBPerDay = gbPerDay
| extend IngestPerMonth = GBPerDay * 30 * PricePerGB, RetentionPerMonth = GBPerDay * max_of(0, {RetentionDays} - FreeDays) * {RetentionPrice}
| extend TotalPerMonth = IngestPerMonth + RetentionPerMonth
| project Plan, GBPerDay = round(GBPerDay, 3), PricePerGB, IngestPerMonth = round(IngestPerMonth, 2), RetentionPerMonth = round(RetentionPerMonth, 2), TotalPerMonth = round(TotalPerMonth, 2)

// Yesterday's billed bytes per row of the similar table.
let measured = table({SimilarTable})
| where TimeGenerated between (startofday(ago(1d)) .. startofday(now()))
| summarize Rows = count(), Bytes = sum(_BilledSize)
| extend BytesPerRow = iff(Rows == 0, real(null), 1.0 * Bytes / Rows), k = 1;
datatable(Plan: string) ["Analytics", "Basic", "Auxiliary"]
| extend PricePerGB = case(Plan == "Analytics", {PriceAnalytics}, Plan == "Basic", {PriceBasic}, Plan == "Auxiliary", {PriceAuxiliary}, real(null)), FreeDays = iff(Plan == "Analytics", {FreeRetentionDays}, 30)
| extend k = 1
| join kind=inner measured on k
| extend GBPerDay = {EventsPerDay} * BytesPerRow / 1e9
| extend IngestPerMonth = GBPerDay * 30 * PricePerGB, RetentionPerMonth = GBPerDay * max_of(0, {RetentionDays} - FreeDays) * {RetentionPrice}
| extend TotalPerMonth = IngestPerMonth + RetentionPerMonth
| project Plan, BytesPerRow = round(BytesPerRow, 1), GBPerDay = round(GBPerDay, 3), PricePerGB, IngestPerMonth = round(IngestPerMonth, 2), RetentionPerMonth = round(RetentionPerMonth, 2), TotalPerMonth = round(TotalPerMonth, 2), Note = iff(isnull(BytesPerRow), "The table had no rows yesterday.", "")
